@AbsoluteValue.sum_le : ∀ {ι : Type u_1} {R : Type u_2} {S : Type u_3} [inst : Semiring R] [inst_1 : Semiring S]
  [inst_2 : PartialOrder S] [IsOrderedRing S] (abv : AbsoluteValue R S) (s : Finset ι) (f : ι → R),
  abv (∑ i ∈ s, f i) ≤ ∑ i ∈ s, abv (f i)

@AbsoluteValue.eval_mvPolynomial_le : ∀ {K : Type u_1} [inst : Field K] {ι : Type u_2} [Finite ι]
  (v : AbsoluteValue K ℝ) {p : MvPolynomial ι K} {N : ℕ},
  p.IsHomogeneous N → ∀ (x : ι → K), v ((eval x) p) ≤ (p.coeff.sum fun x c ↦ v c) * (⨆ i, v (x i)) ^ N

@Finset.le_sum_of_subadditive : ∀ {ι : Type u_1} {M : Type u_2} {N : Type u_3} [inst : AddCommMonoid M]
  [inst_1 : AddCommMonoid N] [inst_2 : Preorder N] [IsOrderedAddMonoid N] (f : M → N),
  f 0 ≤ 0 → (∀ (x y : M), f (x + y) ≤ f x + f y) → ∀ (s : Finset ι) (g : ι → M), f (∑ i ∈ s, g i) ≤ ∑ i ∈ s, f (g i)

@map_nonneg : ∀ {F : Type u_1} {α : Type u_2} {β : Type u_3} [inst : FunLike F α β] [inst_1 : Preorder α]
  [inst_2 : Zero α] [inst_3 : Preorder β] [inst_4 : Zero β] [OrderHomClass F α β] [ZeroHomClass F α β] (f : F) {a : α},
  0 ≤ a → 0 ≤ f a

@map_mul_le_mul : ∀ {F : Type u_1} {α : outParam (Type u_2)} {β : outParam (Type u_3)} {inst : Mul α} {inst_1 : Mul β}
  {inst_2 : LE β} {inst_3 : FunLike F α β} [self : SubmultiplicativeHomClass F α β] (f : F) (a b : α),
  f (a * b) ≤ f a * f b

@Finset.prod_univ_sum : ∀ {ι : Type u_1} {R : Type u_2} [inst : CommSemiring R] [inst_1 : DecidableEq ι]
  {κ : ι → Type u_3} [inst_2 : Fintype ι] (t : (i : ι) → Finset (κ i)) (f : (i : ι) → κ i → R),
  ∏ i, ∑ j ∈ t i, f i j = ∑ x ∈ Fintype.piFinset t, ∏ i, f i (x i)

@eval₂_eq' : ∀ {R : Type u_1} {S₁ : Type u_2} {σ : Type u_3} [inst : CommSemiring R] [inst_1 : CommSemiring S₁]
  [inst_2 : Fintype σ] (g : R →+* S₁) (X : σ → S₁) (f : MvPolynomial σ R),
  eval₂ g X f = ∑ d ∈ f.support, g (f.coeff d) * ∏ i, X i ^ d i
